/**
 * @summary Get location history trail of a member
 */
export const getGetMemberLocationHistoryUrl = (
  userId: string,
  params?: GetMemberLocationHistoryParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/locations/${userId}/history?${stringifiedParams}`
    : `/api/locations/${userId}/history`;
};

